def sortItems(n: int, m: int, group: list[int], beforeItems: list[list[int]]) -> list[int]:
    from collections import defaultdict, deque
    # Assign lone items their own unique group
    next_group = m
    for i in range(n):
        if group[i] == -1:
            group[i] = next_group
            next_group += 1
    item_adj = defaultdict(list)
    item_in = [0] * n
    group_adj = defaultdict(set)
    group_in = [0] * next_group
    for u in range(n):
        for v in beforeItems[u]:
            item_adj[v].append(u)
            item_in[u] += 1
            if group[u] != group[v]:
                if group[u] not in group_adj[group[v]]:
                    group_adj[group[v]].add(group[u])
                    group_in[group[u]] += 1
    def topo(nodes, adj, in_deg):
        q = deque([x for x in nodes if in_deg[x] == 0])
        res = []
        while q:
            curr = q.popleft()
            res.append(curr)
            for nxt in adj[curr]:
                in_deg[nxt] -= 1
                if in_deg[nxt] == 0: q.append(nxt)
        return res if len(res) == len(nodes) else []
    sorted_groups = topo(list(range(next_group)), group_adj, group_in)
    sorted_items = topo(list(range(n)), item_adj, item_in)
    if not sorted_groups or not sorted_items: return []
    group_to_items = defaultdict(list)
    for item in sorted_items:
        group_to_items[group[item]].append(item)
    res = []
    for g in sorted_groups:
        res.extend(group_to_items[g])
    return res

